'use strict';
let S=null, csrf='', selected=null, view='clients', tab='purchases', mobile='details', query='', setup=false, workplaceFilter='', clientQuery='', shopifyPendingQuery='', clientDebtView='debt', reviewKind='all', reviewStatus='pending', reviewSearch='', reviewMonth='', clientSupportOpen=false;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(n||0);
const day=s=>/^\d{4}-\d{2}$/.test(String(s))?new Date(s+'-15T12:00:00').toLocaleDateString('es-CL',{month:'long',year:'numeric'}):s?new Date(String(s).length===10?s+'T12:00:00':s).toLocaleDateString('es-CL',{day:'2-digit',month:'short',year:'numeric'}):'—';
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const initials=n=>n.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('');
const op=()=>Array.from(crypto.getRandomValues(new Uint8Array(20)),x=>x.toString(16).padStart(2,'0')).join('');
function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.add('hidden'),6000)}
async function api(path,data,form=false){const opts={headers:{}};if(data!==undefined){opts.method='POST';opts.headers['X-CSRF-Token']=csrf;if(form)opts.body=data;else{opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}}const r=await fetch('/api/'+path,opts);let j;try{j=await r.json()}catch{throw Error('No se pudo leer la respuesta del servidor.')}if(!r.ok){if(r.status===401&&path!=='login'){showAuth(false)}throw Object.assign(Error(j.error||'No se pudo completar la operación.'),{status:r.status})}return j}
function statusPill(p){return p.pending===0?'<span class="pill green">✓ Pagada</span>':p.due<S.today?'<span class="pill red">Vencida</span>':p.pending<p.amount?'<span class="pill warm">Abono parcial</span>':'<span class="pill">Pendiente</span>'}
function orders(cid){return S.orders.filter(o=>o.client_id===cid)}
function active(cid){return S.orders.filter(o=>(cid==null||o.client_id===cid)&&o.status==='active')}
function installments(cid){const ids=new Set(active(cid).map(o=>o.id));return S.installments.filter(i=>ids.has(i.order_id))}
function balance(cid){return active(cid).reduce((a,o)=>a+o.balance,0)}
function totals(cid){const os=active(cid),ins=installments(cid),ids=new Set(os.map(o=>o.id));return {total:os.reduce((a,o)=>a+o.total,0),paid:os.reduce((a,o)=>a+o.base_paid,0)+S.payments.filter(p=>ids.has(p.order_id)&&!p.reversed).reduce((a,p)=>a+p.amount,0),balance:balance(cid),overdue:ins.filter(i=>i.due<S.today).reduce((a,i)=>a+i.pending,0),month:ins.filter(i=>i.due.slice(0,7)===S.today.slice(0,7)).reduce((a,i)=>a+i.pending,0),next:ins.filter(i=>i.pending>0).sort((a,b)=>a.due.localeCompare(b.due))[0]}}
function stats(cid,source=null){const groups=CindyAnnual.group(source||active(cid));return `<section class="card annual-summary annual-balance-only"><div class="card-head"><h2>Saldo vigente por año</h2></div><table><thead><tr><th>Año</th><th>Saldo vigente</th></tr></thead><tbody>${groups.map(g=>`<tr><th scope="row">${esc(g.year)}</th><td><strong>${money(g.balance)}</strong></td></tr>`).join('')}</tbody></table>${!groups.length?'<p class="subtle">Sin compras registradas.</p>':''}</section>`;}

function receiptCard(r){return `<div class="receipt"><div class="receipt-title"><div class="receipt-icon">▤</div><div><strong>${esc(r.filename)}</strong><small>${day(r.created)}</small><a class="receipt-link" href="/api/receipts/${r.id}/file" target="_blank" rel="noopener">Ver comprobante ↗</a></div></div>${r.status==='pending'?`<div class="receipt-review"><small>◷ Pendiente de revisión<br>El saldo aún no cambia</small><button class="primary" data-action="review" data-id="${r.id}">Revisar abono</button></div>`:`<div class="receipt-review"><span class="pill ${r.status==='confirmed'?'green':'red'}">${r.status==='confirmed'?'✓ Abono confirmado':'Comprobante rechazado'}</span></div>`}</div>`}
function noticeList(cid){return (S.payment_notices||[]).filter(n=>n.client_id===cid).map(n=>`<div class="bubble out">${esc(n.body)}<span class="bubble-time">Confirmación de abono · ${({pending:'Pendiente de envío',sending:'Enviando',sent:'Enviada',review:'Revisar envío',cancelled:'Cancelada',demo:'Simulada · no enviada'})[n.status]||esc(n.status)}</span>${n.error?`<p class="subtle">${esc(n.error)}</p>`:''}${n.status==='pending'?`<button class="text-button" data-action="cancel-notice" data-id="${n.payment_id}">Cancelar aviso</button>`:''}</div>`).join('')}
function chat(cid){const rs=S.receipts.filter(r=>r.client_id===cid);return '<section class="card"><h3>Comprobantes</h3><button class="outline" data-action="upload">＋ Cargar comprobante</button>'+rs.map(receiptCard).join('')+noticeList(cid)+statementHistory(cid)+'</section>';}
function ledgerProducts(order){return order.items?.length?`<ul class="ledger-products">${order.items.map(item=>`<li><span>${esc(item.quantity??1)} ×</span> ${esc(item.title||'Detalle no informado')}</li>`).join('')}</ul>`:'<p class="subtle">Detalle de productos no informado.</p>';}
function ledgerOrderRow(order,archived=false){return `<li class="ledger-purchase" data-ledger-order="${order.id}"><div class="ledger-purchase-date"><time>${day(order.purchased)}</time><small>${esc(order.number)}</small>${archived?(order.status==='restructured'?'':'<span class="pill">Anulada</span>'):order.review?'<span class="pill warm">Por revisar</span>':''}</div><div class="ledger-purchase-products">${ledgerProducts(order)}</div><div class="ledger-purchase-total"><small>Total de la compra</small><strong>${money(order.total)}</strong></div><details class="ledger-order-actions"><summary>Opciones</summary><div>${!archived&&order.balance>0&&!order.review?`<button class="primary" data-action="pay" data-id="${order.id}">Ingresar abono</button>`:''}<button class="text-button" data-action="edit-order-items" data-id="${order.id}">Editar productos</button><button class="text-button" data-action="adjust" data-id="${order.id}">Ajustar compra</button></div></details></li>`;}
function ledgerPaymentRow(payment,order,archived=false){return `<tr ${payment.id?'data-ledger-payment="'+payment.id+'"':''}><td>${payment.date?day(payment.date):'<span class="subtle">Sin fecha registrada</span>'}</td><td>${esc(payment.imported||order?.source==='cxc'?'Abonos realizados':order?.number||'Compra')}${payment.previous?'<small>Pago previo al registro</small>':''}${archived?`<small>${payment.reversed?'Abono anulado':order?.status==='restructured'?'Registro previo a reestructuración':'Compra anulada'}</small>`:''}</td><td class="ledger-payment-amount">${money(payment.amount)}</td><td>${payment.id&&!payment.reversed?`<button class="text-button danger" data-action="reverse" data-id="${payment.id}">Anular</button>`:''}</td></tr>`;}
function ledgerDateKey(value){
 const text=String(value||'');
 if(/^\d{4}-\d{2}-\d{2}$/.test(text))return text;
 if(!text.includes('T'))return '';
 const date=new Date(text);if(Number.isNaN(date.valueOf()))return '';
 const parts=new Intl.DateTimeFormat('en',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'America/Santiago'}).formatToParts(date);
 return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');
}
function clientLedger(cid,compact=false){
  const accountOrders=active(cid).filter(o=>o.source==='cxc'),purchases=active(cid).filter(o=>o.source!=='cxc').slice().sort((a,b)=>String(a.purchased).localeCompare(String(b.purchased))||a.id-b.id),ids=new Set([...purchases,...accountOrders].map(o=>o.id));
  const allOrders=orders(cid),allIds=new Set(allOrders.map(o=>o.id)),lookup=new Map(allOrders.map(o=>[o.id,o]));
  const allPayments=[...S.payments.filter(p=>ids.has(p.order_id)&&!p.reversed),...CindyHistory.payments(S,cid)].sort((a,b)=>String(a.date||'9999').localeCompare(String(b.date||'9999'))||(a.id||0)-(b.id||0));
  const firstPurchase=clientPurchaseRecords(cid).map(o=>ledgerDateKey(o.purchased)).filter(Boolean).sort()[0]||'';
  const earlierPayments=allPayments.filter(p=>firstPurchase&&ledgerDateKey(p.date)&&ledgerDateKey(p.date)<firstPurchase);
  const payments=allPayments.filter(p=>!earlierPayments.includes(p));
  const previous=[...purchases,...accountOrders]
    .filter(o=>o.base_paid>0&&(!firstPurchase||!ledgerDateKey(o.purchased)||ledgerDateKey(o.purchased)>=firstPurchase))
    .map(o=>({order_id:o.id,amount:o.base_paid,previous:true}));
  const archivedOrders=allOrders.filter(o=>o.status!=='active').sort((a,b)=>String(a.purchased).localeCompare(String(b.purchased))||a.id-b.id);
  const archivedPayments=S.payments.filter(p=>allIds.has(p.order_id)&&(p.reversed||!ids.has(p.order_id))).sort((a,b)=>String(a.date).localeCompare(String(b.date))||a.id-b.id);
  const t=totals(cid);
  return `<section class="card client-ledger" aria-label="Cuenta de la clienta">${!compact&&purchases.length?`<div class="card-head"><h3>Compras</h3></div><ul class="ledger-purchases">${purchases.map(o=>ledgerOrderRow(o)).join('')}</ul>`:''}

<section class="ledger-payments"><h3>Abonos realizados</h3>${payments.length||previous.length?`<div class="table-scroll"><table><thead><tr><th>Fecha de pago</th><th>Compra</th><th>Monto</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody>${payments.map(p=>ledgerPaymentRow(p,lookup.get(p.order_id))).join('')}${previous.map(p=>ledgerPaymentRow(p,lookup.get(p.order_id))).join('')}</tbody></table></div>`:'<p class="subtle ledger-empty">Todavía no hay pagos registrados.</p>'}</section>
  <div class="ledger-account-total"><div class="total-row final ledger-current-balance"><span>Saldo vigente</span><strong>${money(t.balance)}</strong></div></div>
  ${archivedOrders.length||archivedPayments.length||earlierPayments.length?`<details class="ledger-archive"><summary>Registros anteriores y anulados</summary>${archivedOrders.length?`<h4>Compras anteriores o anuladas</h4><ul class="ledger-purchases">${archivedOrders.map(o=>ledgerOrderRow(o,true)).join('')}</ul>`:''}${archivedPayments.length||earlierPayments.length?`<h4>Abonos anteriores o anulados</h4><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Compra</th><th>Monto</th><th>Acciones</th></tr></thead><tbody>${earlierPayments.map(p=>ledgerPaymentRow(p,lookup.get(p.order_id))).join('')}${archivedPayments.map(p=>ledgerPaymentRow(p,lookup.get(p.order_id),true)).join('')}</tbody></table></div>`:''}</details>`:''}</section>`;

}
function detail(){
 const cl=S.clients.find(c=>c.id===selected);if(!cl){selected=null;return clientList();}
 const canPay=active(cl.id).some(o=>o.balance>0&&!o.review);
 return `<section class="card ledger-client-header"><button class="text-button" data-action="client-directory">← Clientas</button><div class="ledger-client-heading"><div class="client-avatar">${esc(initials(cl.name))}</div><h2>${esc(cl.name)}</h2><button class="text-button" data-action="edit">Editar ficha</button></div><div class="client-personal-data"><p><small>Código</small>${esc(cl.code||'Sin código')}</p><p><small>Lugar de trabajo</small>${esc(clientWorkplace(cl))}</p><p><small>Teléfono</small>${esc(cl.phone?'+'+cl.phone:cl.raw_phone||'Sin teléfono')}</p><p><small>Correo</small>${esc(cl.email||'Sin correo')}</p><p><small>Etiquetas</small>${clientTags(cl).map(esc).join(' · ')}</p></div>${(S.cxc_accounts||[]).find(a=>a.client_id===cl.id)?.credit?`<p class="info-box">Saldo a favor: ${money((S.cxc_accounts||[]).find(a=>a.client_id===cl.id).credit)}</p>`:''}<div class="statement-actions">${canPay?'<button class="primary" data-action="focus-client-payment">＋ Ingresar abono</button>':''}<button class="outline" data-action="share-statement" data-id="${cl.id}">Enviar estado de cuenta por WhatsApp</button></div></section>${clientPurchaseDetails(cl.id)}<div class="client-account-columns">${clientLedger(cl.id,true)}${CindyClientPayment.view(cl.id)}</div><details class="client-annual-history"><summary>Histórico de compras por año</summary>${CindyHistory.render(S,cl.id,esc,money,day)}${stats(cl.id)}</details><details id="client-ledger-support" class="client-ledger-support" ${clientSupportOpen?'open':''}><summary>Comprobantes e historial</summary>${chat(cl.id)}</details>`;
}
function clientPurchaseActions(o){return `<details class="ledger-order-actions"><summary>Opciones</summary>${o.balance>0&&!o.review?`<button class="outline" data-action="pay" data-id="${o.id}">Ingresar abono</button>`:''}<button class="text-button" data-action="edit-order-items" data-id="${o.id}">Editar productos</button><button class="text-button" data-action="adjust" data-id="${o.id}">Ajustar compra</button></details>`;}
function purchaseDate(value){
 const text=String(value||'');
 if(!text)return 'Sin fecha registrada';
 if(/^\d{4}-\d{2}$/.test(text))return day(text).toLocaleUpperCase('es-CL');
 const date=new Date(text.length===10?text+'T12:00:00-03:00':text);
 if(Number.isNaN(date.valueOf()))return 'Sin fecha registrada';
 return new Intl.DateTimeFormat('es-CL',{day:'2-digit',month:'short',year:'numeric',timeZone:'America/Santiago'}).format(date).replace(/\./g,'').toLocaleUpperCase('es-CL');
}
function clientPurchaseRecords(cid){
 const remote=pendingShopifyOrders().filter(r=>r.client_id===cid),normalized=n=>String(n||'').trim().replace(/^#/,'');
 const same=(a,b)=>a.shopify_id&&b.shopify_id?a.shopify_id===b.shopify_id:Boolean(normalized(a.number)&&normalized(a.number)===normalized(b.number)&&a.total===b.total);
 const detailed=o=>Array.isArray(o.items)&&o.items.some(i=>{const title=String(i.title||'').trim();return title&&!/^(?:pedido|compra)(?:\s*#?\d+)?$/i.test(title)&&!/^(?:saldo|corte)\b/i.test(title);});
 const stored=orders(cid).filter(o=>o.source!=='cxc'&&(o.status==='active'||o.status==='restructured'));
 const entries=remote.map(r=>{
  const matches=stored.filter(o=>same(r,o)),linked=matches.filter(o=>o.status==='active'),available=matches.find(detailed);
  return {...r,items:detailed(r)||!available?r.items:available.items,local:linked.length===1?linked[0]:null};
 });
 for(const o of stored.filter(o=>!remote.some(r=>same(o,r))&&(o.status==='active'||detailed(o))))entries.push({...o,previous:o.status==='restructured',local:o.status==='active'?o:null});
 for(const h of (S.purchase_history||[]).filter(h=>h.client_id===cid&&h.kind==='purchase')){
  const historical={number:h.number,purchased:h.date,total:h.amount,items:h.items,previous:true};
  if(detailed(historical)&&!entries.some(o=>normalized(o.number)===normalized(h.number)))entries.push(historical);
 }
 return entries.sort((a,b)=>String(b.purchased).localeCompare(String(a.purchased))||String(a.number).localeCompare(String(b.number)));
}
function clientPurchaseCard(o){
 const status=o.financial_status==='PARTIALLY_PAID'?'Pago parcial en Shopify':o.financial_status==='PENDING'?'Pago pendiente en Shopify':o.previous?'Compra anterior · detalle de referencia':'';
 return `<article class="client-purchase-card"><h3>COMPRA ${esc(o.number)}</h3><p class="purchase-date">Realizada el ${esc(purchaseDate(o.purchased))}</p>${status?`<small class="subtle purchase-status">${status}</small>`:''}<h4 class="purchase-products-label">Detalle de productos:</h4>${ledgerProducts(o)}<p class="client-purchase-card-total">Total de la compra: <strong>${money(o.total)}</strong></p>${o.local?clientPurchaseActions(o.local):''}</article>`;
}
function clientPurchaseDetails(cid){
 const entries=clientPurchaseRecords(cid);
 return `<section class="card client-purchase-details"><div class="card-head"><h2>Compras</h2><button class="outline" data-action="sync">Actualizar productos de Shopify</button></div>${entries.length?entries.map(clientPurchaseCard).join(''):'<p class="subtle">Todavía no hay productos vinculados a esta ficha. Actualiza Shopify; si el pedido está en Pedidos de Shopify, vincúlalo a esta clienta para mostrar aquí su detalle.</p>'}</section>`;
}
function pendingShopifyOrders(){return S.settings?.shopify_pending_orders||[];}
function pendingShopifyRow(r,index,inFicha=false){
 const cl=S.clients.find(c=>c.id===r.client_id);
 if(inFicha)return clientPurchaseCard(r);
 const store=(S.integrations?.shop||'').split('.myshopify.com')[0];
 return `<article class="order-review-row"><div><strong>${esc(r.number)} · ${esc(cl?.name||r.client_name)}</strong><p>${day(r.purchased)} · <span class="pill warm">${r.financial_status==='PARTIALLY_PAID'?'Pago parcial en Shopify':'Pago pendiente en Shopify'}</span></p>${ledgerProducts(r)}<div class="order-review-amounts"><span>Total de la compra: <b>${money(r.total)}</b></span><span>Saldo informado por Shopify: <b>${money(r.outstanding)}</b></span></div>${cl?`<p class="subtle">Saldo de la ficha según Excel y abonos registrados: <b>${money(balance(cl.id))}</b>. Los abonos realizados están en su ficha.</p>`:'<p class="subtle">Vincula una ficha para consultar sus abonos del Excel. No se ha incorporado este pedido al saldo.</p>'}</div><div class="statement-actions">${cl&&!inFicha?`<button class="outline" data-client="${cl.id}">Ver ficha y abonos</button>`:''}${!inFicha?`<button class="text-button" data-action="link-pending-client" data-id="${index}">${cl?'Cambiar ficha vinculada':'Vincular ficha'}</button>`:''}${store&&r.shopify_numeric_id?`<a class="receipt-link" target="_blank" rel="noopener" href="https://admin.shopify.com/store/${encodeURIComponent(store)}/orders/${encodeURIComponent(r.shopify_numeric_id)}">Abrir en Shopify ↗</a>`:''}</div></article>`;
}
function shopifyPendingClient(cid){
 const list=pendingShopifyOrders().map((r,index)=>({...r,index})).filter(r=>r.client_id===cid);
 if(!list.length)return '';
 return `<section class="card"><div class="card-head"><h3>Pedidos pendientes en Shopify</h3></div><p class="subtle">Productos de los pedidos que Shopify mantiene pendientes. Los abonos y el saldo de tu ficha se conservan según Excel; estos importes no se suman de nuevo.</p>${list.map(r=>pendingShopifyRow(r,r.index,true)).join('')}</section>`;
}
function shopifyPendingView(){
 const q=norm(shopifyPendingQuery).trim(),all=pendingShopifyOrders();
 const tagsFor=r=>{const tags=tagLabels(r.tags||[]),client=S.clients.find(c=>c.id===r.client_id);return tags.length?tags:client?clientTags(client):['Sin etiquetas'];};
 const tagOptions=[...new Map(all.flatMap(r=>tagsFor(r)).map(t=>[norm(t).replace(/\s+/g,' ').trim(),t])).entries()].sort((a,b)=>a[1].localeCompare(b[1],'es')); 
 const list=all.map((r,index)=>({...r,index})).filter(r=>(!workplaceFilter||tagsFor(r).some(t=>norm(t).replace(/\s+/g,' ').trim()===workplaceFilter))&&(!q||norm(r.client_name+' '+r.number+' '+r.phone+' '+tagsFor(r).join(' ')+' '+(S.clients.find(c=>c.id===r.client_id)?.name||'')).includes(q))).sort((a,b)=>b.outstanding-a.outstanding||a.client_name.localeCompare(b.client_name,'es'));
 return `<section class="card"><h2>Clientas con pedidos pendientes en Shopify</h2>${clientDirectoryTabs()}<p>Compras y productos desde Shopify. Los abonos se consultan en la ficha vinculada y se mantienen según Excel.</p><p class="info-box">Por conciliar con la deuda actual. El saldo que Shopify muestra puede incluir abonos ya anotados en Excel; no se suma automáticamente a tu cartera.</p><label>Filtrar por etiquetas<select id="workplace-filter"><option value="">Todas las etiquetas</option>${tagOptions.map(([key,label])=>`<option value="${esc(key)}" ${workplaceFilter===key?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>Buscar clienta o pedido<input id="shopify-pending-search" value="${esc(shopifyPendingQuery)}" placeholder="Nombre, teléfono o número de pedido…"></label><div class="form-actions"><button class="outline" data-action="sync">Actualizar desde Shopify</button></div>${S.settings?.sync_at?`<small>Última consulta: ${esc(new Date(S.settings.sync_at).toLocaleString('es-CL'))}</small>`:''}</section><section class="card"><h3>${list.length} pedidos pendientes</h3>${list.map(r=>pendingShopifyRow(r,r.index)).join('')||'<p class="subtle">No hay pedidos disponibles en esta vista. Actualiza desde Shopify para consultar los pedidos accesibles.</p>'}</section>`;
}
function linkPendingClientModal(index){
 const r=pendingShopifyOrders()[index];if(!r)return;
 modal('Vincular pedido '+r.number,`<form><p>${esc(r.client_name)} · ${day(r.purchased)}</p><label>Ficha existente<select name="client_id" required><option value="">Selecciona la clienta</option>${S.clients.map(c=>`<option value="${c.id}" ${c.id===r.client_id?'selected':''}>${esc(c.name)}${c.code?' · COD '+esc(c.code):''} · ${esc(clientWorkplace(c))}</option>`).join('')}</select></label><p class="info-box">Comprueba que sea la misma persona. Esta vinculación permite ver sus productos y abonos. No cambia la deuda ni asigna abonos a pedidos.</p>${actions}</form>`,f=>api('shopify/pending/link',{...data(f),shopify_id:r.shopify_id,fingerprint:r.fingerprint}));
}
function clientWorkplace(c){
 const explicit=String(c.workplace||c.work||'').trim();if(explicit)return explicit;
 const notes=String(c.notes||'').trim();
 const labeled=notes.match(/(?:^|[·\n])\s*(?:lugar de trabajo|trabajo|empresa|instituci[oó]n)\s*:\s*([^·\n]+)/i);
 if(labeled)return labeled[1].trim();
 const imported=notes.match(/^COD\s+\S+\s*·\s*([^·\n]+)/i);
 return imported&&imported[1].trim()?imported[1].trim():'Sin lugar informado';
}
function tagLabel(value){
 const label=String(value||'').trim().replace(/\s+/g,' '),key=norm(label);
 if(!label||['sin etiquetas','sin etiqueta','sin lugar informado','sin lugar de trabajo','sin informacion','sin codigo','no informado','no aplica','n/a','-','—'].includes(key))return '';
 if(/^(?:clc|clinica las condes)(?:\b|$)/.test(key))return /\bestoril\b/.test(key)?'CLC Estoril':'Clínica Las Condes';
 return label;
}
function tagLabels(tags){
 const values=new Map();for(const raw of tags){const label=tagLabel(raw);if(label&&!values.has(norm(label)))values.set(norm(label),label);}
 return [...values.values()].sort((a,b)=>a.localeCompare(b,'es'));
}
function clientTags(c){
 const values=tagLabels(S.settings?.shopify_client_tags?.[String(c.id)]?.tags||[]);
 if(values.length)return values;
 const workplace=tagLabel(clientWorkplace(c));
 return workplace?[workplace]:['Sin etiquetas'];
}
function clientDirectory(mode=clientDebtView){
 const key=s=>norm(s).replace(/\s+/g,' ').trim(),labels=new Map();
 for(const c of S.clients)for(const label of clientTags(c)){const k=key(label);if(!labels.has(k))labels.set(k,label)}
 const options=[...labels].sort((a,b)=>a[1].localeCompare(b[1],'es'));
 const q=key(clientQuery),filtered=S.clients.filter(c=>(!workplaceFilter||clientTags(c).some(t=>key(t)===workplaceFilter))&&(!q||key(c.name+' '+c.phone+' '+clientTags(c).join(' ')).includes(q)));
 const debtCount=filtered.filter(c=>balance(c.id)>0).length,noDebtCount=filtered.length-debtCount;
 const cs=filtered.filter(c=>mode==='debt'?balance(c.id)>0:balance(c.id)<=0);
 cs.sort((a,b)=>balance(b.id)-balance(a.id)||a.name.localeCompare(b.name,'es')||a.id-b.id);
 const grouped=new Map();for(const c of cs){const k=workplaceFilter||key(clientTags(c)[0]);if(!grouped.has(k))grouped.set(k,{key:k,label:labels.get(k),clients:[],debt:0});const g=grouped.get(k);g.clients.push(c);g.debt+=balance(c.id)}
 const groups=[...grouped.values()].sort((a,b)=>a.label.localeCompare(b.label,'es'));
 return {options,clients:cs,groups,debtCount,noDebtCount,debt:cs.reduce((sum,c)=>sum+balance(c.id),0)};
}
function clientDirectoryTabs(){
 const debt=S.clients.filter(c=>balance(c.id)>0).length,review=(S.settings?.shopify_review_orders||[]).filter(r=>r.status==='pending').length;
 return `<div class="form-actions client-directory-tabs" role="group" aria-label="Clientas por saldo">${[['debt','Clientas con deuda',debt],['no-debt','Clientas sin deuda',S.clients.length-debt],['shopify','Pedidos de Shopify',pendingShopifyOrders().length],['review','Por revisar',review]].map(([key,label,count])=>`<button type="button" class="${clientDebtView===key?'primary':'outline'}" data-directory-debt="${key}" aria-pressed="${clientDebtView===key}">${label} (${count})</button>`).join('')}</div>`;
}
function clientList(){
 if(clientDebtView==='shopify')return shopifyPendingView();
 if(clientDebtView==='review')return clientDirectoryTabs()+orderReviewView();
 const d=clientDirectory(),ids=new Set(d.clients.map(c=>c.id));return `${clientDebtView==='debt'?`<details class="client-annual-history"><summary>Saldos por año</summary>${stats(null,active(null).filter(o=>ids.has(o.client_id)))}</details>`:''}<section class="card client-directory-controls"><div class="section-label"><h2>${clientDebtView==='debt'?'Clientas con deuda':'Clientas sin deuda'}</h2><div><button class="outline" data-action="sync">Actualizar Shopify</button> <button class="outline" data-action="cxc-review">Importar Excel Cindy Lú</button> <button class="outline" data-action="import">Importar Excel / CSV</button></div></div>${clientDirectoryTabs()}${S.settings?.shopify_tags_error?`<p class="info-box">${esc(S.settings.shopify_tags_error)}</p>`:''}${clientDebtView==='no-debt'?'<p class="subtle">Clientas sin saldo pendiente en CXC ni en compras nuevas. Sus fichas, compras históricas y abonos se conservan.</p>':''}<div class="directory-filters"><label>Filtrar por etiquetas<select id="workplace-filter"><option value="">Todas las etiquetas</option>${d.options.map(([key,label])=>`<option value="${esc(key)}" ${workplaceFilter===key?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>Buscar clienta o etiqueta<input id="directory-search" autocomplete="off" placeholder="Nombre, teléfono o etiqueta…" value="${esc(clientQuery)}"></label></div><div class="directory-summary"><span>${d.clients.length} ${d.clients.length===1?'clienta':'clientas'} · ${clientDebtView==='debt'?'Ordenadas de mayor a menor deuda dentro de cada etiqueta':'Ordenadas por etiqueta y nombre'}</span><div><small>Deuda total de la selección</small><strong>${money(d.debt)}</strong></div></div></section>${d.groups.map(g=>`<section class="workplace-group" aria-label="${esc(g.label)}"><div class="workplace-group-heading"><div><h2>${esc(g.label)}</h2><span>${g.clients.length} ${g.clients.length===1?'clienta':'clientas'}</span></div><strong>${money(g.debt)}</strong></div><div class="client-list">${g.clients.map(c=>`<button class="client-tile" data-client="${c.id}"><div class="client-avatar">${esc(initials(c.name))}</div><h3>${esc(c.name)}</h3><p>${clientTags(c).map(esc).join(' · ')}${c.phone?' · +'+esc(c.phone):''}</p><strong>${money(balance(c.id))}</strong><small>${balance(c.id)>0?'Deuda total pendiente':'Sin deuda'}</small></button>`).join('')}</div></section>`).join('')}${!d.clients.length?'<div class="card empty"><h2>Sin coincidencias</h2><p>Prueba con otro nombre o selecciona otra etiqueta.</p></div>':''}`;
}
function reminders(){return `<div class="card"><div class="card-head"><h2>Cobros programados</h2><span class="pill">Hora local del dispositivo</span></div><div class="info-box">Los cobros se envían solo con el servidor encendido, WhatsApp configurado, envíos habilitados y plantilla aprobada. Se pausan si la clienta tiene un comprobante pendiente de revisión.</div>${S.reminders.map(r=>`<div class="list-line"><div class="grow"><strong>${esc(S.clients.find(c=>c.id===r.client_id)?.name)}</strong><p class="subtle">${new Date(r.at).toLocaleString('es-CL')} · ${esc(r.body)}</p>${r.error?`<p class="danger">${esc(r.error)}</p>`:''}</div><span class="pill">${({pending:'Programado',sent:'Enviado',cancelled:'Cancelado',review:'Revisar',sending:'Enviando'})[r.status]||esc(r.status)}</span>${r.status==='pending'?`<button data-action="cancel-reminder" data-id="${r.id}" class="text-button">Cancelar</button>`:''}</div>`).join('')||'<div class="empty"><h2>Todo a su tiempo</h2><p>Abre una clienta y elige «Programar cobro» para añadir su recordatorio.</p></div>'}</div>`}
function receipts(){return `<div class="card"><div class="card-head"><h2>Comprobantes recibidos</h2><p>La foto no modifica la deuda</p></div>${S.receipts.map(r=>`<div class="list-line"><div class="grow"><strong>${esc(S.clients.find(c=>c.id===r.client_id)?.name)}</strong><p class="subtle">${esc(r.filename)} · ${day(r.created)}</p></div><span class="pill ${r.status==='confirmed'?'green':''}">${({pending:'Pendiente',confirmed:'Confirmado',rejected:'Rechazado'})[r.status]}</span><button class="outline" data-client="${r.client_id}">Ver ficha</button></div>`).join('')||'<div class="empty"><h2>Nada pendiente</h2><p>Los comprobantes se guardarán aquí y en la ficha de cada clienta.</p></div>'}</div>`}
function configuration(){const cfg=S.settings;const mode=cfg.shopify_credit_mode||'credit_when_paid';const defIns=cfg.shopify_default_installments||0;return `<div class="settings-grid"><section class="card"><div class="integration"><div class="mark">S</div><div><h3>Shopify · Enlace de clientas y ventas</h3><p>${esc(S.integrations.shop||'cindylu.myshopify.com')}</p></div><span class="pill ${S.integrations.shopify?'green':''}">${S.integrations.shopify?'Credenciales configuradas':'Por enlazar'}</span></div><p>Completa los productos de las compras importadas desde Excel sin cambiar sus saldos ni abonos. Las ventas nuevas de Shopify quedan pendientes de incorporación y no generan deuda automáticamente.</p><form id="shopify-form" style="margin-top:14px"><div class="fields"><label class="full">Dominio de tu tienda Shopify<input name="shopify_domain" value="${esc(S.integrations.shop||'cindylu.myshopify.com')}" placeholder="cindylu.myshopify.com" required></label></div><p class="info-box">Para conectar la app creada en Dev Dashboard, agrega SHOPIFY_DOMAIN, SHOPIFY_CLIENT_ID y SHOPIFY_CLIENT_SECRET en Render → Environment. El servidor renovará el acceso automáticamente.</p><div class="info-box">${cfg.sync_at?'Última sincronización: '+new Date(cfg.sync_at).toLocaleString('es-CL'):'Todavía no se ha ejecutado una sincronización.'}<br>${cfg.shopify_auto_sync?'Sincronización automática cada 5 minutos.':'Primero prueba la conexión y sincroniza manualmente.'}${cfg.shopify_sync_summary?`<br>${cfg.shopify_sync_summary.linked} compras vinculadas · ${cfg.shopify_sync_summary.updated} actualizadas · ${cfg.shopify_sync_summary.pending} ventas nuevas sin incorporar · ${cfg.shopify_sync_summary.conflict} coincidencias por revisar.`:''}</div><div class="info-box">Solo se vinculan compras con número, total y datos de contacto coincidentes. Los pedidos antiguos requieren acceso adicional de Shopify.</div><button type="button" class="outline" data-action="order-review">Abrir revisión de pedidos</button><div class="form-actions"><button type="submit" class="outline">Guardar dominio</button><button type="button" class="outline" data-action="test-shopify">Probar conexión</button><button type="button" class="primary" data-action="sync">↻ Actualizar productos de Shopify</button></div></form></section><section class="card"><div class="integration"><div class="mark">◔</div><div><h3>WhatsApp Business</h3><p>Mensajes y comprobantes</p></div><span class="pill ${S.integrations.whatsapp?'green':''}">${S.integrations.whatsapp?'Credenciales configuradas':'Sin conectar'}</span></div><p>Requiere WhatsApp Business Platform de Meta y una dirección HTTPS pública para recibir mensajes.</p><div class="info-box">No basta con tener WhatsApp Business en el celular. El número debe incorporarse a la integración oficial; conservarlo en la app depende de la modalidad de conexión disponible.</div><p class="subtle">La recepción de comprobantes nunca confirma una transferencia bancaria.</p></section><section class="card"><h2>Mensajes y respuestas</h2><form id="settings-form"><label class="check-label"><input type="checkbox" name="sending" ${cfg.sending?'checked':''}> Habilitar envíos reales de WhatsApp</label><label class="check-label"><input type="checkbox" name="auto_reply" ${cfg.auto_reply?'checked':''}> Responder al recibir un comprobante</label><label class="check-label"><input name="payment_notify" type="checkbox" ${cfg.payment_notify?'checked':''}> Activar por defecto el aviso al confirmar abonos</label><label>Mensaje al confirmar un pago<textarea name="payment_text" rows="4">${esc(cfg.payment_text)}</textarea></label><p class="chat-help">Variables: {nombre}, {monto}, {compra}, {saldo_compra}, {saldo_total}, {fecha}. Se completan con el pago confirmado.</p><h3>Estados de cuenta en PDF</h3><div class="fields"><label>Plantilla con encabezado Documento PDF<input name="statement_template" value="${esc(cfg.statement_template)}" placeholder="estado_cuenta_cindy_lu"></label><label>Idioma<input name="statement_language" value="${esc(cfg.statement_language)}"></label></div><p class="chat-help">Fuera de la conversación de 24 horas, usa una plantilla aprobada con PDF y dos variables: nombre y saldo. Consulta el texto y la estructura en la guía.</p><label>Respuesta automática<textarea name="reply_text" rows="3">${esc(cfg.reply_text)}</textarea></label><div class="fields"><label>Plantilla aprobada en Meta<input name="template" value="${esc(cfg.template)}" placeholder="aviso_cindy_lu"></label><label>Idioma de la plantilla<input name="template_language" value="${esc(cfg.template_language)}"></label></div><p class="chat-help">Plantilla con dos variables de texto: nombre y mensaje. Debe estar aprobada para su contenido. No se enviará nada sin credenciales y autorización de la clienta.</p><div class="form-actions"><button class="primary">Guardar configuración</button></div></form></section><section class="card"><h2>Tus datos, contigo</h2><p class="info-box">Descarga un respaldo de las clientas, compras, abonos y comprobantes ya descargados. Guárdalo en un lugar privado.</p><a href="/api/backup" class="receipt-link">↓ Descargar respaldo completo</a><h3 class="section-label">Acceso desde otros dispositivos</h3><p>Esta versión puede probarse en Windows y Mac. Para acceder desde el teléfono fuera de casa necesita un servidor con HTTPS. Consulta LEEME-PRIMERO.txt.</p><p class="chat-help">No requiere una cuenta de ChatGPT. La versión local no está publicada en internet.</p></section></div>`}
let renderedPageKey='';
function render(fromNavigation=false){if(!S)return;if(['overview','shopify-sales','order-review'].includes(view)){if(view==='order-review')clientDebtView='review';view='clients';selected=null;}const titles={field:['Cobro en terreno','Elige el lugar, busca la clienta y registra el abono.'],clients:['Clientas','Compras, abonos y saldo en una sola ficha.'],receipts:['Comprobantes','Revisa primero. Confirma después.'],reminders:['Cobros programados','Acompaña cada cuota con un recordatorio.'],settings:['Configuración','Conecta tu tienda a tu manera.']};$('#page-title').textContent=titles[view][0];$('#page-subtitle').textContent=titles[view][1];$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#pending-count').textContent=S.receipts.filter(r=>r.status==='pending').length;
$('#demo-label').classList.toggle('hidden',!S.demo);$('#connection').textContent=S.demo?'WhatsApp · Muestra':S.integrations.whatsapp?'WhatsApp configurado':'WhatsApp sin conectar';$('#connection').className='pill '+(S.integrations.whatsapp?'green':'');$('#sync-notice').textContent=S.settings.sync_error;$('#sync-notice').classList.toggle('hidden',!S.settings.sync_error);const content={field:CindyField.view,'order-review':orderReviewView,clients:()=>selected?detail():clientList(),receipts,reminders,settings:configuration};$('#content').innerHTML=content[view]();$('#refresh-status').textContent=S.demo?'Datos ficticios · Entorno de demostración':'Actualizado '+new Date().toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'});bindContent();const pageKey=JSON.stringify([view,selected,clientDebtView,tab,mobile]);if(fromNavigation||pageKey!==renderedPageKey)window.scrollTo({top:0,left:0,behavior:'instant'});renderedPageKey=pageKey;}
async function refresh(renderNow=true){S=await api('state');if(S.season)CindySeasons.apply(S.season);if(renderNow)render()}
function choose(id){clientSupportOpen=false;selected=Number(id);query='';$('#search').value='';view='clients';tab='purchases';$('#suggestions').classList.add('hidden');$('#search').setAttribute('aria-expanded','false');render(true);$('.sidebar').classList.remove('open')}
function suggest(){query=$('#search').value;const q=norm(query.trim());const box=$('#suggestions');if(!q){box.classList.add('hidden');$('#search').setAttribute('aria-expanded','false');return}const matches=S.clients.filter(c=>norm(c.name+' '+c.phone+' '+clientWorkplace(c)+' '+clientTags(c).join(' ')).includes(q)).slice(0,20);box.innerHTML=matches.map(c=>`<button role="option" data-client="${c.id}"><div class="client-avatar">${esc(initials(c.name))}</div><div>${esc(c.name)}<small>${c.phone?'+'+esc(c.phone):'Sin teléfono'}</small></div><strong>${money(balance(c.id))}</strong></button>`).join('')||'<p>No hay coincidencias por nombre, teléfono o lugar de trabajo.</p>';box.classList.remove('hidden');$('#search').setAttribute('aria-expanded','true');box.querySelectorAll('button').forEach(b=>b.onclick=()=>choose(b.dataset.client))}
function modal(title,html,submit){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();const form=$('#modal-body form');if(form&&submit)form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button[type=submit]');b.disabled=true;try{await submit(form);$('#modal').close();await refresh();toast('Cambios guardados.')}catch(err){toast(err.message)}finally{b.disabled=false}}}
const actions='<div class="form-actions"><button type="button" data-close>Cancelar</button><button type="submit" class="primary">Guardar</button></div>';
const data=f=>Object.fromEntries(new FormData(f));
function newClient(){modal('Nueva clienta',`<form><div class="fields"><label class="full">Nombre completo<input name="name" required maxlength="150" placeholder="Nombre y apellido"></label><label>WhatsApp<input name="phone" placeholder="+56 9 1234 5678"></label><label>Correo<input name="email" type="email"></label><label class="full">Notas<textarea name="notes" rows="2"></textarea></label></div><label class="check-label"><input type="checkbox" name="consent"> La clienta autorizó recibir mensajes por WhatsApp</label>${actions}</form>`,async f=>{const d=data(f);d.consent=f.consent.checked;const r=await api('clients',d);selected=r.id;view='clients'})}
function paymentModal(oid,rid=null){const noticeDraft={notify:!!S.settings.payment_notify,noticeTemplate:CindyNotices.template(S.settings)};const r=rid?S.receipts.find(r=>r.id===rid):null;const cid=r?r.client_id:(oid?S.orders.find(o=>o.id===oid)?.client_id:selected);const eligible=active(cid).filter(o=>o.balance>0&&!o.review);if(!eligible.length){toast('No hay compras disponibles con saldo pendiente; revisa la ficha.');return}oid=oid||eligible[0].id;const operation=op();modal(r?'Revisar y confirmar comprobante':'Ingresar abono',`${r?(r.mime.startsWith('image/')?`<img class="receipt-preview" src="/api/receipts/${r.id}/file" alt="Comprobante recibido">`:'')+`<a class="receipt-link" href="/api/receipts/${r.id}/file" target="_blank" rel="noopener">Abrir comprobante completo ↗</a>`:''}<form><div class="info-box">${r?'Comprueba el ingreso en tu banco y escribe el monto real. La imagen por sí sola no acredita el pago.':'Registra solo pagos que ya hayas verificado.'} El abono se descontará del saldo pendiente de la compra elegida.</div><div class="fields"><label class="full">Compra a la que se aplica<select name="order_id">${eligible.map(o=>`<option value="${o.id}" ${o.id===oid?'selected':''}>${esc(o.number)} · ${money(o.balance)} pendiente</option>`).join('')}</select></label><label>Monto confirmado<input name="amount" type="number" min="1" step="1" required placeholder="Ej. 20000"></label><label>Fecha de pago<input name="date" type="date" value="${S.today}" required></label><label>Medio de pago<select name="method"><option value="transferencia">Transferencia</option><option value="efectivo">Efectivo</option><option value="otro">Otro</option></select></label><label>Nota<input name="note" maxlength="1000" placeholder="Referencia bancaria (opcional)"></label></div><label class="check-label"><input type="checkbox" required> Verifiqué que el pago fue recibido</label>${CindyNotices.editor('payment',noticeDraft.notify,noticeDraft.noticeTemplate,'Elige la compra e ingresa el monto para ver el mensaje.',false,CindyNotices.hint(S.clients.find(c=>c.id===cid),S.settings,S.integrations,S.demo))}<div class="form-actions">${r?`<button type="button" class="danger" id="reject-receipt">Rechazar comprobante</button>`:''}<button type="submit" class="primary">✓ Confirmar y descontar</button></div></form>`,f=>api('payments',{...data(f),receipt_id:rid,operation,notify:f.notify.checked,notice_template:$('#payment-notice-template').value}));const noticeForm=$('#modal-body form');const updateNotice=CindyNotices.bind('payment',()=>noticeDraft,draft=>Object.assign(noticeDraft,draft),()=>{const order=S.orders.find(o=>o.id===Number(noticeForm.order_id.value));return CindyNotices.values(S.clients.find(c=>c.id===cid),order,noticeForm.amount.value,noticeForm.date.value,balance(cid));});for(const input of [noticeForm.order_id,noticeForm.amount,noticeForm.date])input.addEventListener('input',updateNotice);updateNotice();if(r)$('#reject-receipt').onclick=async()=>{try{await api('receipts/'+rid+'/reject',{});$('#modal').close();await refresh();toast('Comprobante rechazado. El saldo no cambió.')}catch(e){toast(e.message)}}}
function upload(){modal('Cargar comprobante',`<form><p class="info-box">Se guardará como pendiente. No descontará dinero hasta que confirmes el abono.</p><label>Archivo (JPG, PNG, WEBP o PDF, hasta 8 MB)<input type="file" name="file" required accept="image/png,image/jpeg,image/webp,application/pdf"></label>${actions}</form>`,f=>{const fd=new FormData(f);fd.append('client_id',selected);return api('receipts',fd,true)})}
function remind(cid){modal('Programar recordatorio',`<form><div class="fields"><label class="full">Fecha y hora (hora local del dispositivo)<input name="at" type="datetime-local" required></label><label class="full">Mensaje<textarea name="body" rows="4" required maxlength="1000">Hola, ${esc(S.clients.find(c=>c.id===cid)?.name.split(' ')[0])}. Te recordamos que tienes un saldo pendiente de ${money(balance(cid))}. Gracias por tu compra en Cindy Lú.</textarea></label></div><p class="info-box">Para enviarlo automáticamente, WhatsApp debe estar conectado y la plantilla aprobada. Se pausa si hay comprobantes por revisar.</p>${actions}</form>`,f=>{const d=data(f);return api('reminders',{...d,at:new Date(d.at).toISOString(),client_id:cid})})}
async function action(name,id){try{switch(name){case'client-directory':selected=null;clientSupportOpen=false;view='clients';render();break;case'order-review':view='clients';selected=null;clientDebtView='review';render();break;case'review-shop-order':shopOrderReviewModal(id);break;case'link-pending-client':linkPendingClientModal(id);break;case'new':newClient();break;case'statement':statementModal(id||null);break;case'adjust':adjustModal(id);break;case'mark-seen':await api('settings',{mark_seen_order_id:id});await refresh();toast('Venta marcada como revisada.');break;case'edit-client-id':editClientById(id);break;case'edit-order-items':editOrderItemsModal(id);break;case'share-statement':shareStatementModal(id);break;case'open-whatsapp':openClientWhatsApp(id);break;case'explain':explainModal(id);break;case'cxc-review':reviewCindy();break;case'cancel-notice':await api('payments/'+id+'/notification/cancel',{});await refresh();break;case'edit':editClient();break;case'import':importClients();break;case'focus-client-payment':$('#client-payment-panel')?.scrollIntoView({behavior:'smooth',block:'nearest'});$('#client-payment-amount')?.focus();break;case'pay':paymentModal(id);break;case'review':paymentModal(null,id);break;case'upload':upload();break;case'quick':$('#message-draft').value=S.settings.reply_text;$('#message-draft').focus();break;case'remind':remind(id);break;case'cancel-reminder':await api('reminders/'+id+'/cancel',{});await refresh();break;case'test-shopify':toast('Probando conexión…');const connection=await api('shopify/test',{});toast('Conexión verificada: '+connection.shop);break;case'sync':toast('Consultando Shopify…');const r=await api('shopify/sync',{});await refresh();toast(r.linked+' vinculadas, '+r.updated+' actualizadas, '+r.pending+' nuevas sin incorporar y '+r.conflict+' por revisar.');break;case'reverse':modal('Anular abono',`<form><p class="info-box">El monto volverá al saldo pendiente de la compra. Se conservará el historial.</p><label>Motivo de la anulación<textarea name="reason" minlength="5" required rows="3"></textarea></label>${actions}</form>`,f=>api('payments/'+id+'/reverse',data(f)));break}}catch(e){toast(e.message)}}
function bindContent(){CindyClientPayment.bind();const pq=$('#shopify-pending-search');if(pq)pq.oninput=()=>{shopifyPendingQuery=pq.value;const pos=pq.selectionStart;render();const input=$('#shopify-pending-search');input.focus();input.setSelectionRange(pos,pos)};$$('[data-directory-debt]').forEach(b=>b.onclick=()=>{clientDebtView=b.dataset.directoryDebt;render()});const support=$('#client-ledger-support');if(support)support.ontoggle=()=>{clientSupportOpen=support.open;};CindyField.bind();bindOrderReview();const wf=$('#workplace-filter');if(wf)wf.onchange=()=>{workplaceFilter=wf.value;render()};const ds=$('#directory-search');if(ds)ds.oninput=()=>{clientQuery=ds.value;const pos=ds.selectionStart;render();const field=$('#directory-search');field.focus();field.setSelectionRange(pos,pos)};$$('[data-client]').forEach(b=>b.onclick=()=>choose(b.dataset.client));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,Number(b.dataset.id)));$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$$('[data-mobile]').forEach(b=>b.onclick=()=>{mobile=b.dataset.mobile;render()});const sf=$('#send-form');if(sf)sf.onsubmit=async e=>{e.preventDefault();const draft=$('#message-draft').value,b=sf.querySelector('[type=submit]');b.disabled=true;try{await api('messages',{client_id:selected,body:draft});await refresh();toast('Mensaje enviado.')}catch(err){toast(err.message)}finally{b.disabled=false}};const cc=$('#client-consent');if(cc)cc.onchange=async()=>{try{await api('consent/'+selected,{consent:cc.checked});await refresh(false)}catch(e){toast(e.message)}};const cfg=$('#settings-form');if(cfg)cfg.onsubmit=async e=>{e.preventDefault();try{await api('settings',{...data(cfg),sending:cfg.sending.checked,auto_reply:cfg.auto_reply.checked,payment_notify:cfg.payment_notify.checked});await refresh();toast('Configuración guardada.')}catch(err){toast(err.message)}};const shf=$('#shopify-form');if(shf)shf.onsubmit=async e=>{e.preventDefault();try{await api('settings',data(shf));await refresh();toast('Enlace y reglas de Shopify guardados.')}catch(err){toast(err.message)}}}
function showAuth(isSetup){window.CindyActivity?.stop();CindyCalm.stop();setup=isSetup;$('#auth').classList.remove('hidden');$('#shell').classList.add('hidden');window.CindyIntro?.start();$('#auth-title').textContent=isSetup?'Tu tienda comienza aquí':'Bienvenida de nuevo';$('#auth-desc').textContent=isSetup?'Crea tu acceso privado. Elige una contraseña de al menos 12 caracteres.':'Un solo lugar para tus clientas, compras y pagos.';$('#login-submit').textContent=isSetup?'Crear mi acceso →':'Entrar a mi tienda →';$('#login-form').password.autocomplete=isSetup?'new-password':'current-password';$('#login-form').password.minLength=isSetup?12:1}
let firstSessionCheck=true;
async function start(){const s=await api('session');const returning=firstSessionCheck&&s.authenticated;firstSessionCheck=false;if(s.season)CindySeasons.apply(s.season);if(!s.authenticated){showAuth(s.setup);if(s.demo){$('#auth-hint').innerHTML='<button type="button" id="enter-demo" class="outline">Explorar demostración →</button>';$('#enter-demo').onclick=async()=>{await api('demo',{});await start()}}return}csrf=s.csrf;if(window.CindyActivity?.expired()){await api('logout',{});S=null;showAuth(false);return}window.CindyActivity?.start(async()=>{S=null;showAuth(false);try{await api('logout',{})}catch{}});if(returning){try{const place=JSON.parse(sessionStorage.getItem('cindyWorkspace')||'null');if(place){view=['clients','field','receipts','settings'].includes(place.view)?place.view:'clients';selected=Number(place.selected)||null}}catch{}}window.CindyIntro?.stop();$('#auth').classList.add('hidden');$('#shell').classList.remove('hidden');await refresh();if(S.demo&&S.clients.length&&!selected){selected=S.clients.find(c=>c.id===1)?.id||S.clients[0].id;render()}if(returning)CindySeasons.welcome();CindyCalm.start({delay:returning?4200:0});}
$('#login-form').onsubmit=async e=>{e.preventDefault();const b=$('#login-submit');b.disabled=true;try{const d=data(e.target);try{if($('#remember-user').checked)localStorage.setItem('cindyRememberedUser',d.email);else localStorage.removeItem('cindyRememberedUser')}catch{}if(setup){await api('setup',d);toast('Acceso creado.')}const s=await api('login',d);csrf=s.csrf;window.CindyActivity?.reset();$('#login-form').password.value='';await start()}catch(err){toast(err.message)}finally{b.disabled=false}};
$('#statement-open').onclick=()=>statementModal();$('#new-client').onclick=newClient;$('#search').oninput=suggest;$('#search').onfocus=()=>{if(S)suggest()};$('#search').onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();$('#suggestions button')?.focus()}if(e.key==='Escape')$('#suggestions').classList.add('hidden')};$('#suggestions').onkeydown=e=>{const bs=$$('#suggestions button'),i=bs.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();bs[(i+1)%bs.length]?.focus()}if(e.key==='ArrowUp'){e.preventDefault();bs[(i-1+bs.length)%bs.length]?.focus()}if(e.key==='Escape'){$('#suggestions').classList.add('hidden');$('#search').focus()}};
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap')){$('#suggestions').classList.add('hidden');$('#search').setAttribute('aria-expanded','false')}if(e.target.closest('[data-close]'))$('#modal').close()});$('#close-modal').onclick=()=>$('#modal').close();$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');$$('nav [data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;if(view==='clients'){selected=null;clientDebtView='debt';}render();$('.sidebar').classList.remove('open')});$('#logout').onclick=async()=>{await api('logout',{});CindyField.reset();CindyClientPayment.reset();S=null;selected=null;showAuth(false)};
setInterval(async()=>{if(!S||CindyClientPayment.hasDraft()||(view==='field'&&CindyField.hasDraft())||document.hidden||$('#modal').open||!$('#suggestions').classList.contains('hidden')||document.activeElement?.matches('input,textarea,select')||$('#message-draft')?.value)return;try{const old=JSON.stringify(S);await refresh(false);if(JSON.stringify(S)!==old)render()}catch{if(S)$('#refresh-status').textContent='Sin conexión · Reintentando'}},10000);
window.addEventListener('pagehide',()=>{try{sessionStorage.setItem('cindyWorkspace',JSON.stringify({view,selected}))}catch{}});
// Restored pages recheck authentication and inactivity.
window.addEventListener('pageshow',e=>{if(e.persisted)window.location.reload()});
start().catch(e=>toast(e.message));

function editClient(){const c=S.clients.find(c=>c.id===selected);modal('Editar ficha',`<form><div class="fields"><label class="full">Nombre<input name="name" value="${esc(c.name)}" required></label><label>Teléfono<input name="phone" value="${esc(c.phone)}"></label><label>Correo<input name="email" type="email" value="${esc(c.email)}"></label><label class="full">Notas<textarea name="notes">${esc(c.notes)}</textarea></label></div>${actions}</form>`,f=>api('clients/'+selected,data(f)))}
function importClients(){modal('Importar clientas y compras',`<form><p class="info-box">Primera hoja, hasta 1000 filas. Encabezados obligatorios: <b>nombre, telefono</b>.<br>Opcionales: <b>correo, deuda (o saldo), total, articulo, fecha</b>.</p><a href="/api/import/template" class="receipt-link">↓ Descargar plantilla CSV para Excel</a><label>Archivo Excel (.xlsx) o CSV<input type="file" name="file" accept=".xlsx,.csv" required></label><div class="form-actions"><button class="primary" type="submit">Revisar archivo</button></div></form>`,async f=>{const result=await api('import/preview',new FormData(f),true);setTimeout(()=>{const valid=result.rows.filter(r=>r.data);modal('Revisar importación',`<form><p class="info-box">${valid.length} filas válidas · ${result.rows.length-valid.length} con error. Solo se importarán las válidas. Se omiten teléfonos que ya existan.</p><div class="table-scroll"><table><thead><tr><th>Fila</th><th>Clienta</th><th>Artículo</th><th>Deuda / Error</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${r.row}</td><td>${esc(r.data?.name||'—')}</td><td>${esc(r.data?.article||'—')}</td><td>${r.error?esc(r.error):money(r.data.debt)}</td></tr>`).join('')}</tbody></table></div><div class="form-actions"><button class="primary" type="submit">Confirmar importación</button></div></form>`,async()=>{const r=await api('import/confirm',{rows:valid.map(v=>({...v.data,installments:0}))});setTimeout(()=>toast(r.inserted+' clientas importadas; '+r.skipped+' teléfonos existentes omitidos.'),100)})},100)})}

try{const remembered=localStorage.getItem('cindyRememberedUser');if(remembered){$('#login-form').email.value=remembered;$('#remember-user').checked=true}}catch{}
$('#remember-user').onchange=()=>{if(!$('#remember-user').checked){try{localStorage.removeItem('cindyRememberedUser')}catch{}}};


function reviewCindy(){
 modal('Reestructurar histórico y CXC',`<form><p class="info-box">Selecciona juntos los dos Excel. CLUB CINDYLÚ aporta las fichas y el monto final comprado por año, con detalle mensual. CXC aporta el saldo del último corte mensual y los abonos registrados. No se repartirán abonos entre compras sin número de pedido.</p><label>Histórico CLUB y CXC del año vigente<input type="file" name="files" accept=".xlsx" multiple required></label><div class="form-actions"><button type="submit" class="primary">Revisar datos y cambios de saldo</button></div></form>`,async f=>{
  const r=await api('import/cindy-review',new FormData(f),true);
  const x=r.summary,v=r.review;
  setTimeout(()=>modal('Revisar reestructuración',`<form><p class="info-box">${x.contacts} clientas · ${x.historical_purchases} compras históricas · ${x.historical_months} resúmenes mensuales en total.<br>Corte ${esc(x.period)}: deuda por cobrar ${money(x.receivable)} · saldo a favor ${money(x.credit)} · saldo neto ${money(x.net_balance)}.<br>Abonos del corte: ${money(x.current_payments)}, ya descontados una sola vez.</p><p>Se conservarán ${x.payment_entries} registros de abonos y referencias a últimos pagos. Los últimos abonos repetidos en varios cortes no se suman otra vez. Hay ${x.ambiguous_historical_rows} filas históricas con código A y detalle PEDIDO que quedan por revisar, fuera de la suma de compras. ${x.invalid_phones} teléfonos conservarán el original para revisión. Hay ${x.unassigned_historical_records||0} registros históricos sin clienta identificada (${money(x.unassigned_historical_total||0)}), conservados para revisión sin asignarlos a otra persona.</p><p>Se archivarán ${v.archive_count||0} compras de importaciones Excel anteriores. Sus abonos e historial se conservan. Se guardará un respaldo privado antes de aplicar.</p>${v.already_imported?'<p class="info-box">Estos archivos ya fueron importados. No se duplicarán.</p>':''}${v.blocked?.length?`<div class="review-banner"><strong>Hay registros que requieren conciliación</strong><ul>${v.blocked.map(b=>`<li>${esc(b)}</li>`).join('')}</ul></div>`:''}<details><summary>Ver cambios de saldo por clienta (${v.changes?.length||0})</summary><div class="table-scroll"><table><thead><tr><th>Clienta</th><th>Saldo anterior</th><th>Deuda CXC</th><th>A favor</th></tr></thead><tbody>${(v.changes||[]).map(c=>`<tr><td>${esc(c.name)}<small>COD ${esc(c.code)}</small></td><td>${money(c.before)}</td><td>${money(c.after)}</td><td>${money(c.credit)}</td></tr>`).join('')}</tbody></table></div></details><details><summary>Avisos de los archivos (${r.warnings.length})</summary><ul>${r.warnings.map(w=>`<li>${esc(w.sheet||w.period||'')} · fila ${esc(w.row||'—')} · COD ${esc(w.code)}: ${esc(({missing_balance:'saldo ausente',balance_difference:'diferencia entre saldo y movimientos',repeated_payment:'abono repetido por revisar',unidentified_historical_client:'compra histórica sin clienta identificada'})[w.kind]||w.kind)}</li>`).join('')}</ul></details>${!v.blocked?.length?`<div class="form-actions"><button type="submit" class="primary">${v.already_imported?'Cerrar revisión':'Aplicar reestructuración'}</button></div>`:''}</form>`,!v.blocked?.length?async()=>{if(v.already_imported)return;const result=await api('import/cindy-confirm',{token:r.token});setTimeout(()=>toast(`Reestructuración lista: ${result.clients} clientas, ${result.historical_records} registros históricos y saldo por cobrar ${money(result.receivable)}.`),100);}:null),100);
 });
}

function buildClientExplanation(cid,customOpts=null){const cl=S.clients.find(c=>c.id===cid),os=active(cid).filter(o=>o.balance>0),cfg=customOpts||S.settings||{};if(!cl)return '';const total=os.reduce((n,o)=>n+o.total,0),pending=os.reduce((n,o)=>n+o.balance,0),rpl=t=>String(t).replace(/\{nombre\}/gi,cl.name.split(' ')[0]).replace(/\{saldo\}/gi,money(pending)).replace(/cuotas?/gi,'cuenta');let lines=[rpl(cfg.explain_intro||'Hola, {nombre}. Este es el detalle actualizado de tu cuenta en Cindy Lú.'),'',`Compras y saldos de corte registrados: ${money(total)}`,`Total abonado: ${money(total-pending)}`,`SALDO PENDIENTE: ${money(pending)}`,''];for(const o of os){lines.push(o.source==='cxc'?`Saldo de corte CXC · ${day(o.purchased)}`:`Compra ${o.number} del ${day(o.purchased)}`,o.items.map(i=>`${i.quantity} × ${i.title}`).join(', '),`Total: ${money(o.total)} · Abonado: ${money(o.total-o.balance)} · Saldo: ${money(o.balance)}`);for(const p of S.payments.filter(p=>p.order_id===o.id&&!p.reversed))lines.push(`Abono del ${day(p.date)}: ${money(p.amount)}`);lines.push('');}if(cfg.explain_bank)lines.push(cfg.explain_bank);lines.push(rpl(cfg.explain_outro||'Cualquier duda con tu saldo o abonos, avísanos.'));return lines.join('\n');}
function adjustModal(oid){const o=S.orders.find(x=>x.id===oid);if(!o)return;const paid=S.payments.filter(p=>p.order_id===oid&&!p.reversed).reduce((n,p)=>n+p.amount,0);modal('Ajustar saldo · '+o.number,`<form><p class="info-box">Los abonos ya confirmados (${money(paid)}) se conservan.</p><div class="fields"><label>Total de la compra<input name="total" type="number" min="1" step="1" value="${o.total}" required></label><label>Pagos previos al registro<input name="base_paid" type="number" min="0" step="1" value="${o.base_paid}" required></label></div>${actions}</form>`,f=>api('orders/'+oid+'/adjust',{...data(f),count:0}));}


function shareStatementModal(cid){
 const cl=S.clients.find(c=>c.id===cid);if(!cl)return;
 const cfg=S.settings||{},replace=t=>String(t).replace(/\{nombre\}/gi,cl.name.split(' ')[0]).replace(/\{saldo\}/gi,money(balance(cid)));
 const message=[replace(cfg.explain_intro||'Hola, {nombre}. Te compartimos tu estado de cuenta de TIENDA CINDY LÚ.'),'Saldo vigente: '+money(balance(cid)),cfg.explain_bank||'',replace(cfg.explain_outro||'Cualquier duda, escríbenos y lo revisamos juntas.')].filter(Boolean).join('\n\n');
 modal('Enviar estado de cuenta por WhatsApp',`
 <p><strong>${esc(cl.name)}</strong> · ${esc(cl.phone||'Sin teléfono')}</p>
 <label>Mensaje editable<textarea id="share-statement-text" rows="7">${esc(message)}</textarea></label>
 <p>Descarga el PDF y abre el chat de la clienta. El mensaje aparecerá preparado; adjunta el PDF descargado desde el clip de WhatsApp y revisa antes de enviar.</p>
 <div class="form-actions"><a class="outline" href="/api/clients/${cid}/statement.pdf" download>1. Descargar PDF</a><button type="button" class="primary" id="share-statement-open">2. Abrir WhatsApp de la clienta</button></div>`);
 $('#share-statement-open').onclick=()=>openClientWhatsApp(cid,$('#share-statement-text').value);
}

function openClientWhatsApp(cid,message=null){
 const cl=S.clients.find(c=>c.id===cid);if(!cl)return;
 const raw=String(cl.phone||'').trim();
 let phone=raw.replace(/[\s()+.-]/g,'');
 if(/^9\d{8}$/.test(phone))phone='56'+phone;
 if(!/^[1-9]\d{7,14}$/.test(phone)){toast('Completa un teléfono válido con código de país en «Editar ficha».');return;}
 const text=message??('Hola, '+cl.name.split(' ')[0]+'. Te compartimos tu saldo vigente en TIENDA CINDY LÚ: '+money(balance(cid))+'. Si necesitas el detalle de tus compras y abonos, te enviamos tu estado de cuenta. Cualquier duda, escríbenos.');
 window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');
}

function explainModal(cid){
 const cfg=S.settings||{};
 const introVal=cfg.explain_intro??'Hola, {nombre} ✨ Aquí está el detalle actualizado de tu cuenta en Cindy Lú Tienda:';
 const bankVal=cfg.explain_bank??'Datos para transferencia: Cindy Lú Tienda (envíanos tu comprobante por WhatsApp al transferir).';
 const outroVal=cfg.explain_outro??'Cualquier duda con el saldo o algún abono avísanos y lo revisamos juntas 💛';
 const txt=buildClientExplanation(cid);
 modal('Mensaje personalizable para copiar a WhatsApp',`
  <p class="info-box" style="margin-bottom:8px">Puedes editar libremente el texto de abajo antes de copiarlo, o personalizar tu plantilla fija para que todas las clientas salgan con tu propio saludo y datos de transferencia.</p>
  <textarea id="explain-text" rows="11" style="font-family:monospace;font-size:12.5px;line-height:1.45;width:100%">${esc(txt)}</textarea>
  <div class="form-actions" style="margin-top:8px;justify-content:space-between">
   <button type="button" class="outline" id="toggle-tpl-editor">✎ Personalizar mi plantilla fija</button>
   <div style="display:flex;gap:8px">
    <button type="button" class="outline" id="open-explain-whatsapp">Abrir WhatsApp ↗</button><button type="button" class="primary" id="copy-explain">📋 Copiar mensaje para WhatsApp</button>
   </div>
  </div>
  <div id="tpl-editor-box" class="custom-tpl-box hidden">
   <strong style="display:block;margin-bottom:8px">Plantilla personalizada (usa {nombre} y {saldo} si deseas)</strong>
   <div class="fields">
    <label class="full">Saludo inicial<input id="tpl-intro" value="${esc(introVal)}"></label>
    <label class="full">Datos de transferencia / medio de pago<input id="tpl-bank" value="${esc(bankVal)}"></label>
    <label class="full">Mensaje final de despedida<input id="tpl-outro" value="${esc(outroVal)}"></label>
   </div>
   <div style="display:flex;flex-wrap:wrap;gap:12px;margin:8px 0">
    <label class="check-label"><input type="checkbox" id="tpl-sum" ${cfg.explain_show_summary!==false?'checked':''}> Resumen total</label>
    <label class="check-label"><input type="checkbox" id="tpl-pay" ${cfg.explain_show_payments!==false?'checked':''}> Compras y abonos</label>
    <label class="check-label"><input type="checkbox" id="tpl-bnk" ${cfg.explain_show_bank!==false?'checked':''}> Datos transferencia</label>
   </div>
   <div class="form-actions">
    <button type="button" class="primary" id="save-tpl-btn">✓ Guardar plantilla para todas las clientas</button>
   </div>
  </div>
 `);
 const collectOpts=()=>({
  explain_intro:$('#tpl-intro').value,
  explain_bank:$('#tpl-bank').value,
  explain_outro:$('#tpl-outro').value,
  explain_show_summary:$('#tpl-sum').checked,
  explain_show_payments:$('#tpl-pay').checked,
  explain_show_installments:false,
  explain_show_bank:$('#tpl-bnk').checked
 });
 const updateLive=()=>{
  $('#explain-text').value=buildClientExplanation(cid,collectOpts());
 };
 ['#tpl-intro','#tpl-bank','#tpl-outro','#tpl-sum','#tpl-pay','#tpl-bnk'].forEach(sel=>{
  const el=$(sel);if(el){el.oninput=updateLive;el.onchange=updateLive;}
 });
 $('#toggle-tpl-editor').onclick=()=>$('#tpl-editor-box').classList.toggle('hidden');
 $('#save-tpl-btn').onclick=async()=>{
  const opts=collectOpts();
  await api('settings',opts);
  Object.assign(S.settings,opts);
  updateLive();
  toast('Plantilla personalizada guardada.');
 };
 $('#open-explain-whatsapp').onclick=()=>openClientWhatsApp(cid,$('#explain-text').value);
 $('#copy-explain').onclick=()=>{
  const el=$('#explain-text');el.select();
  try{navigator.clipboard.writeText(el.value)}catch{document.execCommand('copy')}
  toast('Mensaje copiado al portapapeles listo para pegar en WhatsApp.');
 };
}
function statementHistory(cid){return (S.statement_sends||[]).filter(x=>x.client_id===cid).map(x=>`<div class="bubble out"><strong>▤ Estado de cuenta PDF</strong><p>${esc(x.body)}</p><a class="receipt-link" href="/api/statement-sends/${x.id}/file">↓ Ver copia del documento</a><span class="bubble-time">${new Date(x.created).toLocaleString('es-CL')} · ${esc(({preparing:'Preparando',sending:'Enviando',sent:'Aceptado por WhatsApp',delivered:'Entregado',read:'Leído',review:'Revisar envío',failed:'No entregado',demo:'Demostración · No enviado'})[x.status]||x.status)}</span>${x.error?`<p class="subtle">${esc(x.error)}</p>`:''}</div>`).join('')}
function statementModal(initial=null){
 let chosen=null,preview=null,operation='',generation=0,busy=false;
 modal('Descargar o enviar estado de cuenta PDF',`<form id="statement-form"><label>Buscar y seleccionar clienta<input id="statement-search" placeholder="Escribe un nombre, apellido o teléfono…" autocomplete="off" role="combobox" aria-expanded="true" aria-controls="statement-results"></label><div id="statement-results" class="statement-results" role="listbox" aria-label="Coincidencias de clientas"></div><section id="statement-preview" class="statement-preview"><p>Selecciona una clienta para descargar su PDF con logo o copiar su desglose.</p></section><div id="statement-feedback" role="status" class="subtle"></div><div class="form-actions"><button type="button" id="statement-close">Cerrar</button></div></form>`);
 const input=$('#statement-search'),results=$('#statement-results'),area=$('#statement-preview');
 const select=async cid=>{chosen=cid;const cl=S.clients.find(c=>c.id===cid);if(!cl)return;input.value=cl.name;results.innerHTML='';area.innerHTML=`<div class="statement-recipient"><strong>${esc(cl.name)}</strong><span>WhatsApp: ${cl.phone?'+'+esc(cl.phone):'Sin teléfono'}</span></div><div class="total-row"><span>Saldo total pendiente</span><strong>${money(balance(cid))}</strong></div><div style="display:flex;gap:10px;margin-top:12px"><a class="primary" style="text-decoration:none;padding:10px 16px;border-radius:999px" href="/api/clients/${cid}/statement.pdf">↓ Descargar PDF con logo</a><button type="button" class="outline" id="open-explain-from-stmt">📋 Copiar mensaje WhatsApp</button></div>`;$('#open-explain-from-stmt').onclick=()=>$('#modal').close()||explainModal(cid);};
 const suggestClients=()=>{const q=norm(input.value.trim()),all=S.clients.filter(c=>norm(c.name+' '+c.phone+' '+clientWorkplace(c)+' '+clientTags(c).join(' ')).includes(q)),cs=all.slice(0,20);results.innerHTML=cs.map(c=>`<button type="button" role="option" data-statement-client="${c.id}"><span><strong>${esc(c.name)}</strong><small>${c.phone?'+'+esc(c.phone):'Sin teléfono'}</small></span><b>${money(balance(c.id))}</b></button>`).join('')||'<p>Sin coincidencias.</p>';results.querySelectorAll('button').forEach(b=>b.onclick=()=>select(Number(b.dataset.statementClient)))};
 input.oninput=suggestClients;input.onfocus=()=>{if(!chosen)suggestClients()};$('#statement-close').onclick=()=>$('#modal').close();
 if(initial)select(initial);else suggestClients();input.focus();
}
function editClientById(cid){
 const c=S.clients.find(x=>x.id===cid);if(!c)return;
 modal('Datos de la clienta · '+c.name,`<form><div class="fields"><label class="full">Nombre completo<input name="name" value="${esc(c.name)}" required></label><label>WhatsApp (con código 569)<input name="phone" value="${esc(c.phone)}" placeholder="56912345678"></label><label>Correo electrónico<input name="email" type="email" value="${esc(c.email)}"></label><label class="full">Lugar de trabajo / Código / Notas<textarea name="notes" rows="2">${esc(c.notes)}</textarea></label></div>${actions}</form>`,f=>api('clients/'+cid,data(f)));
}
function editOrderItemsModal(oid){
 const o=S.orders.find(x=>x.id===oid);if(!o)return;
 const currentItems=o.items.map(i=>(i.quantity>1?i.quantity+'x ':'')+i.title).join(', ');
 modal('Editar productos y pedido · '+o.number,`<form><div class="info-box">Puedes detallar los productos comprados (separados por coma) o ajustar el número y fecha del pedido.</div><div class="fields"><label>Número de pedido<input name="number" value="${esc(o.number)}" required></label><label>Fecha de compra<input name="purchased" type="date" value="${esc(String(o.purchased).slice(0,10))}" required></label><label class="full">Productos comprados (separados por coma)<textarea name="article" rows="3" required>${esc(currentItems)}</textarea></label></div>${actions}</form>`,f=>api('orders/'+oid+'/items',data(f)));
}
function orderReviewView(){
 const all=S.settings.shopify_review_orders||[];
 const kinds={negative:'Montos negativos',amount:'Otros montos',difference:'Diferencias con registros',new:'Nuevas sin incorporar'};
 const list=all.map((r,index)=>({...r,index})).filter(r=>(reviewKind==='all'||r.kind===reviewKind)&&(reviewStatus==='all'||r.status===reviewStatus)&&(!reviewMonth||r.purchased.slice(0,7)===reviewMonth)&&(!reviewSearch||norm(r.number+' '+r.client_name).includes(norm(reviewSearch)))).sort((a,b)=>b.purchased.localeCompare(a.purchased));
 const pending=all.filter(r=>r.status!=='reviewed');
 const remoteMoney=(raw,currency)=>{const n=Number(raw);return raw!==''&&Number.isFinite(n)?new Intl.NumberFormat('es-CL',{maximumFractionDigits:20}).format(n)+' '+esc(currency||'CLP'):esc(raw||'No informado')};
 return `<section class="card"><h2>Revisión de pedidos ingresados con montos negativos</h2><p>Un saldo negativo en Shopify puede aparecer después de editar una compra marcada como pagada. Revisa el pedido y los abonos reales antes de decidir su saldo.</p><div class="info-box">${pending.filter(r=>r.kind==='negative').length} con montos negativos · ${pending.filter(r=>r.kind==='amount'||r.kind==='difference').length} con otras diferencias · ${pending.filter(r=>r.kind==='new').length} nuevas sin incorporar.<br>Los casos pendientes tienen distintos motivos. La fecha de cada pedido permite comprobar si corresponde a este mes.</div><div class="fields"><label>Motivo<select id="order-review-kind"><option value="all">Todos los motivos</option>${Object.entries(kinds).map(([v,l])=>`<option value="${v}" ${reviewKind===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Estado<select id="order-review-status">${[['pending','Por revisar'],['reviewed','Revisados'],['all','Todos']].map(([v,l])=>`<option value="${v}" ${reviewStatus===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Mes del pedido<input id="order-review-month" type="month" value="${esc(reviewMonth)}"></label><label>Buscar pedido o clienta<input id="order-review-search" value="${esc(reviewSearch)}" placeholder="Ej. 6406 o nombre"></label></div><div class="form-actions"><button class="outline" data-action="sync">Actualizar desde Shopify</button></div></section><section class="card order-review-list"><h3>${list.length} pedidos en esta vista</h3>${list.length?list.map(r=>`<article class="order-review-row"><div><strong>${esc(r.number)} · ${esc(r.client_name)}</strong><p>Fecha del pedido: ${day(r.purchased)} · <span class="pill ${r.kind==='negative'?'red':'warm'}">${esc(kinds[r.kind]||r.kind)}</span> · ${r.status==='reviewed'?'Revisado el '+day(r.reviewed_at):'Por revisar'}</p>${r.items?.length?`<div class="articles">${r.items.map(i=>`<span class="article">${esc(i.quantity)} × ${esc(i.title)}</span>`).join('')}</div>`:''}<div class="order-review-amounts"><span>Total Shopify: <b>${remoteMoney(r.total,r.currency)}</b></span><span>Saldo Shopify: <b>${remoteMoney(r.outstanding,r.currency)}</b></span>${r.local_order_id?`<span>Total registrado aquí: <b>${money(r.local_total)}</b></span><span>Saldo registrado aquí: <b>${money(r.local_balance)}</b></span>`:'<span>Sin compra local vinculada</span>'}</div><p>${esc(r.reason)}</p>${r.note?`<p><b>Observación:</b> ${esc(r.note)}</p>`:''}${r.previous_note?`<p class="subtle">El pedido cambió desde la revisión anterior. Observación anterior: ${esc(r.previous_note)}</p>`:''}</div><div class="statement-actions">${r.shopify_numeric_id?`<a class="receipt-link" target="_blank" rel="noopener" href="https://admin.shopify.com/store/${encodeURIComponent((S.integrations.shop||'').split('.myshopify.com')[0])}/orders/${encodeURIComponent(r.shopify_numeric_id)}">Abrir en Shopify ↗</a>`:''}${r.client_id?`<button class="outline" data-client="${Number(r.client_id)}">Ver ficha y abonos</button>`:''}<button class="primary" data-action="review-shop-order" data-id="${r.index}">Registrar revisión</button></div></article>`).join(''):`<p class="info-box">No hay pedidos que coincidan con estos filtros.${all.length?'':' Pulsa «Actualizar desde Shopify» para cargar la lista de revisión.'}</p>`}</section>`;
}
function bindOrderReview(){
 const controls=[['#order-review-kind',v=>reviewKind=v],['#order-review-status',v=>reviewStatus=v],['#order-review-month',v=>reviewMonth=v]];
 for(const [selector,set] of controls){const el=$(selector);if(el)el.onchange=()=>{set(el.value);render()};}
 const input=$('#order-review-search');if(input)input.oninput=()=>{reviewSearch=input.value;const pos=input.selectionStart;render();const field=$('#order-review-search');field.focus();field.setSelectionRange(pos,pos)};
}
function shopOrderReviewModal(index){
 const r=(S.settings.shopify_review_orders||[])[index];if(!r)return;
 modal('Revisar pedido '+r.number,`<form><p><b>${esc(r.client_name)}</b> · ${day(r.purchased)}</p><p class="info-box">${esc(r.reason)}</p><label>Estado de la revisión<select name="status"><option value="pending" ${r.status==='pending'?'selected':''}>Mantener por revisar</option><option value="reviewed" ${r.status==='reviewed'?'selected':''}>Revisado por la encargada</option></select></label><label>Observaciones de la encargada<textarea name="note" rows="5" maxlength="2000" required minlength="5" placeholder="Qué se comprobó y qué falta resolver">${esc(r.note||'')}</textarea></label><p class="subtle">Guardar esta revisión conserva la observación. Para descontar un abono confirmado, regístralo en la ficha de la clienta. Este botón no cambia el saldo ni incorpora ventas nuevas.</p>${actions}</form>`,f=>api('shopify/review',{...data(f),shopify_id:r.shopify_id,fingerprint:r.fingerprint}));
}










